    static let shared: CatalogBundle = {
        guard let data = Data(base64Encoded: encodedCatalog, options: .ignoreUnknownCharacters),
              let decoded = try? JSONDecoder().decode(CatalogBundle.self, from: data) else {
            return CatalogBundle(
                subjects: [],
                anatomies: [],
                outfits: [],
                poses: [],
                duo_poses: [],
                settings: [],
                lightings: [],
                character_banks: [:],
                anatomy_pos: [:],
                anatomy_neg: [:]
            )
        }
        return decoded
    }()

